//! Application branding: the window / taskbar icon. The same artwork is embedded into
//! cad360.exe as its file icon by `build.rs` (assets/cad360.ico); both are generated by
//! `packaging/icon/make-icon.ps1`.

/// 256 × 256 RGBA rendering of the CAD360 icon.
const ICON_PNG: &[u8] = include_bytes!("../assets/cad360-256.png");

/// Window icon for `egui::ViewportBuilder::with_icon`.
pub fn app_icon() -> egui::IconData {
    decode_rgba(ICON_PNG).unwrap_or_default()
}

/// Decodes a PNG into unmultiplied 8-bit RGBA.
fn decode_rgba(bytes: &[u8]) -> Option<egui::IconData> {
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(png::Transformations::normalize_to_color8());
    let mut reader = decoder.read_info().ok()?;
    let mut buf = vec![0; reader.output_buffer_size()?];
    let info = reader.next_frame(&mut buf).ok()?;
    buf.truncate(info.buffer_size());
    let rgba = match info.color_type {
        png::ColorType::Rgba => buf,
        png::ColorType::Rgb => buf.chunks_exact(3).flat_map(|p| [p[0], p[1], p[2], 255]).collect(),
        png::ColorType::GrayscaleAlpha => buf.chunks_exact(2).flat_map(|p| [p[0], p[0], p[0], p[1]]).collect(),
        png::ColorType::Grayscale => buf.iter().flat_map(|&v| [v, v, v, 255]).collect(),
        png::ColorType::Indexed => return None,
    };
    Some(egui::IconData { rgba, width: info.width, height: info.height })
}

#[cfg(test)]
mod tests {
    #[test]
    fn icon_decodes_to_256_rgba() {
        let icon = super::app_icon();
        assert_eq!((icon.width, icon.height), (256, 256));
        assert_eq!(icon.rgba.len(), 256 * 256 * 4);
        // transparent corner, opaque tile centre
        assert_eq!(icon.rgba[3], 0);
        assert_eq!(icon.rgba[(128 * 256 + 128) * 4 + 3], 255);
    }
}
